WITH with_windows AS (SELECT *, SUM(salary) OVER (PARTITION BY job_title ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_sum_salary, MAX(salary) OVER (PARTITION BY job_title ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_max_salary, MIN(salary) OVER (PARTITION BY job_title ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_min_salary FROM employees), filtered AS (SELECT *, INITCAP(TRIM(job_title)) job_title_title, COALESCE(job_title, 'N/A') job_title_filled FROM with_windows WHERE job_title IN ('Analyst', 'Engineer')), enriched AS (SELECT id, email, dept_id, manager_id, salary, hire_date, is_remote, running_min_salary, job_title_filled, NTILE(3) OVER (PARTITION BY job_title ORDER BY running_min_salary DESC, id) running_min_salary_bucket, ROUND(running_max_salary / SUM(running_max_salary) OVER (PARTITION BY job_title), 4) running_max_salary_share FROM filtered), enriched_employees AS (SELECT s.id, s.dept_id, s.salary, s.hire_date, s.is_remote, s.running_min_salary, s.job_title_filled, s.running_min_salary_bucket, s.running_max_salary_share, d.dept_name FROM enriched s LEFT JOIN departments d ON s.dept_id = d.id WHERE d.location = 'New York'), scored AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY running_min_salary_bucket, id) row_seq, PERCENT_RANK() OVER w_recent running_min_salary_bucket_percent_rank, SUM(running_min_salary_bucket) OVER (ORDER BY running_min_salary_bucket, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_running_min_salary_bucket, AVG(running_max_salary_share) OVER (ORDER BY running_min_salary_bucket, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) running_max_salary_share_avg_6, LAG(salary, 2) OVER (PARTITION BY dept_name ORDER BY running_max_salary_share, id) prev_salary FROM enriched_employees WINDOW w_recent AS (PARTITION BY dept_id, dept_name ORDER BY running_min_salary_bucket DESC)), enriched_employees_2 AS (SELECT a.*, b.location, b.budget, b.dept_name AS department_dept_name FROM scored a LEFT JOIN departments b ON a.dept_id = b.id) SELECT id, dept_id, salary, hire_date, is_remote, running_min_salary, running_min_salary_bucket, running_max_salary_share, dept_name, CASE WHEN dept_name RLIKE '^(Finance|Engineering)$' THEN 'GROUP_B' WHEN dept_name RLIKE '^(Sales|Marketing)$' THEN 'GROUP_A' ELSE 'OTHER_ZONE' END AS dept_name_zone FROM enriched_employees_2 ORDER BY running_min_salary_bucket DESC NULLS FIRST, running_max_salary_share;
